package ai.interviewiq.api.service;
import ai.interviewiq.api.entity.*; import ai.interviewiq.api.exception.ApiException; import ai.interviewiq.api.repository.*; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.font.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.util.*;
@Service public class PdfReportService { private final InterviewSessionRepository sessions; private final InterviewFeedbackRepository feedbacks; private final QuestionFeedbackRepository questionFeedbacks; public PdfReportService(InterviewSessionRepository s,InterviewFeedbackRepository f,QuestionFeedbackRepository q){sessions=s;feedbacks=f;questionFeedbacks=q;}
 @Transactional(readOnly=true) public byte[] generate(Long userId,Long id){InterviewSession s=sessions.findByIdAndUserId(id,userId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Interview not found."));InterviewFeedback f=feedbacks.findByInterviewSessionId(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Feedback not found."));try(PDDocument doc=new PDDocument();ByteArrayOutputStream out=new ByteArrayOutputStream()){PDPage page=new PDPage();doc.addPage(page);try(PDPageContentStream c=new PDPageContentStream(doc,page)){float y=760;c.beginText();c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),18);c.newLineAtOffset(48,y);c.showText("INTERVIEWIQ AI — Interview Report");c.endText();y-=34;y=line(c,"Candidate: "+s.getUser().getDisplayName(),y,true);y=line(c,"Role: "+s.getJobRole().getName()+"  |  Company: "+s.getCompany().getName(),y,false);y=line(c,"Difficulty: "+s.getDifficultyLevel().getDisplayName()+"  |  Type: "+s.getInterviewTemplate().getName(),y,false);y=line(c,"Completed: "+s.getCompletedAt(),y,false);y-=8;y=line(c,"Overall score: "+f.getOverallScore()+"/100",y,true);y=line(c,"Assessment: "+f.getOverallAssessment(),y,false);y-=8;y=line(c,"Strengths: "+safe(f.getStrengths()),y,false);y=line(c,"Improvement areas: "+safe(f.getImprovementAreas()),y,false);y=line(c,"Recommended actions: "+safe(f.getRecommendedActions()),y,false);y-=10;for(InterviewQuestion q:s.getQuestions()){if(y<105)break;y=line(c,"Q"+q.getSequenceNumber()+": "+q.getQuestionText(),y,true);y=line(c,"Answer: "+(q.getAnswer()==null?"Not answered":q.getAnswer().getAnswerText()),y,false);} }doc.save(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException("Could not generate report.",e);} }
 private static float line(PDPageContentStream c,String value,float y,boolean bold)throws IOException{c.beginText();c.setFont(new PDType1Font(bold?Standard14Fonts.FontName.HELVETICA_BOLD:Standard14Fonts.FontName.HELVETICA),10);c.newLineAtOffset(48,y);c.showText(trim(value));c.endText();return y-16;} private static String trim(String s){return s==null?"":s.replaceAll("[\\r\\n]+"," ").substring(0,Math.min(110,s.length()));} private static String safe(String value){return value==null?"":value.replaceAll("[\\[\\]\"]"," ");}
}
